      0,
    ),
  ).to.deep.eq({
    x: "2030-01-01T00:00:00.000Z",
    y: 3,
    raw: point.raw,
    selected: point.selected,
  });
  expect(
    applyLayerTransforms(
      point,
      {
        ...chartLayer1,
        fields: ["field1"],
        transforms: [
          { type: "self", add: 1, axis: "y" },
          // Case where chartLayer1 is not time aligned with chartLayer3
          {
            type: "derived",
            layerId: chartLayer3.id,
            axis: "y",
            multiply: true,
          },
        ],
      },
      testData,
      0,
    ),
  ).to.deep.eq(null);
});

test("formatYValue", () => {
